// --resume inherits the cost-cap bookkeeping from history: if an earlier run
// could not report provider costs, the amount spent is unknown and the cap can
// no longer be proven, so that state must not be reset by starting over.
const historyCostUnknown = maxCost !== undefined && previousRecords.some((record) => !(record?.usage?.providerCosts?.length))
const historyCost = previousRecords.reduce((sum, record) => sum + (record.usage?.providerCosts ?? []).filter((cost) => cost.currency === costCurrency).reduce((costSum, cost) => costSum + cost.amount, 0), 0)
let consumedCostUnknown = historyCostUnknown
let consumedCost = historyCost
let budgetStopped = false

const trial = plan.trial
if (budgetStopped) break
// Re-check the inherited cap before spending an attempt: an unknown
// historical cost or an already exhausted budget stops the batch instead
// of silently resetting the cost boundary on resume.
if (maxCost !== undefined && (consumedCostUnknown || consumedCost > maxCost)) { budgetStopped = true; break }

if (!usage?.providerCosts?.length) consumedCostUnknown = true
consumedCost += taskCost
// History is counted from the inherited total, so the cap is evaluated on
// this run's real spend instead of restarting the accounting.
if (consumedCostUnknown || consumedCost > maxCost) budgetStopped = true

// On resume the workspace may already exist. A fixture file that is
// already present is left exactly as found (it may hold the interrupted
// run's output or a local edit), so only missing fixtures are filled in;
// switching to exclusive creation must not abort the resumed batch with
// EEXIST either.
try {
  await writeFile(target, value, { flag: 'wx' })
} catch (error) {
  if (error.code !== 'EEXIST') throw error
}

